import{c as e}from"./app.756eaed4.js";import{_ as i}from"./plugin-vue_export-helper.21dcd24c.js";const o={},a=e('<h1 id="overview" tabindex="-1"><a class="header-anchor" href="#overview" aria-hidden="true">#</a> Overview</h1><p>Designed for application developers, database administrators, and system programmers, the IMS Explorer for VS Code extension provides built-in features to access IMS inside Visual Studio Code IDE. By combining multiple activities into one environment, IMS Explorer for VS Code promotes modern development practices and simplifies complex IMS database development tasks. IMS Explorer for VS Code currently supports the following actions:</p><ul><li>IMS projects to organize SQL queries and import DBDs/PSBs from the IMS catalog.</li><li>IMS connections tree view to add, group, expand and collapse IMS database connections and browse DBDs, PSBs, and PCBs.</li><li>IMS Catalog and database exploration, including viewing DDL, segments, fields, and source.</li><li>Interactive hierarchical visualization of DBDs and PSBs with zoom controls and multiple view modes.</li><li>Table views for quick navigation across database definitions.</li><li>Enhanced SQL query editing with CodeLens connection selection and execution against selected IMS database connections.</li><li>Query history and CSV export for result sets.</li><li>Workspace settings including Java selection, JVM arguments, logging options, and storage location selection.</li></ul>',3);function t(n,s){return a}var d=i(o,[["render",t]]);export{d as default};
